    54	static uint64_t isqrt_u64(uint64_t value)
    55	{
    56	  uint64_t result = 0;
    57	  uint64_t bit = (uint64_t)1 << 62;
    58	
    59	  while (bit > value)
    60	    {
    61	      bit >>= 2;
    62	    }
    63	
    64	  while (bit != 0)
    65	    {
    66	      if (value >= result + bit)
    67	        {
    68	          value -= result + bit;
    69	          result = (result >> 1) + bit;
    70	        }
    71	      else
    72	        {
    73	          result >>= 1;
    74	        }
    75	
    76	      bit >>= 2;
    77	    }
    78	
    79	  return result;
    80	}
