   157	static void print_audio_stats(const int16_t *samples, size_t sample_count,
   158	                              uint64_t timestamp_ms)
   159	{
   160	  int16_t min_sample = 0;
   161	  int16_t max_sample = 0;
   162	  int64_t sum = 0;
   163	  uint64_t sum_squares = 0;
   164	  unsigned int zero_count = 0;
   165	  unsigned int i;
   166	  int64_t mean;
   167	  uint64_t rms;
   168	
   169	  if (samples == NULL || sample_count == 0)
   170	    {
   171	      return;
   172	    }
   173	
   174	  min_sample = samples[0];
   175	  max_sample = samples[0];
   176	  for (i = 0; i < sample_count; i++)
   177	    {
   178	      int32_t sample = samples[i];
   179	
   180	      if (sample < min_sample)
   181	        {
   182	          min_sample = sample;
   183	        }
   184	
   185	      if (sample > max_sample)
   186	        {
   187	          max_sample = sample;
   188	        }
   189	
   190	      if (sample == 0)
   191	        {
   192	          zero_count++;
   193	        }
   194	
   195	      sum += sample;
   196	      sum_squares += (uint64_t)((int64_t)sample * sample);
   197	    }
