   182	static int es7210_write_reg(struct i2c_master_s *i2c, uint8_t addr,
   183	                            uint32_t frequency, uint8_t reg, uint8_t value)
   184	{
   185	  struct i2c_msg_s msg;
   186	  uint8_t buffer[2];
   187	  int ret;
   188	
   189	  buffer[0] = reg;
   190	  buffer[1] = value;
   191	
   192	  msg.frequency = frequency;
   193	  msg.addr      = addr;
   194	  msg.flags     = 0;
   195	  msg.buffer    = buffer;
   196	  msg.length    = sizeof(buffer);
   197	
   198	  ret = I2C_TRANSFER(i2c, &msg, 1);
   199	  if (ret < 0)
   200	    {
   201	      auderr("ERROR: ES7210 register 0x%02x write failed: %d\n", reg, ret);
   202	    }
   203	
   204	  return ret;
   205	}
   206	
   207	static int es7210_read_reg(struct i2c_master_s *i2c, uint8_t addr,
   208	                           uint32_t frequency, uint8_t reg, uint8_t *value)
   209	{
   210	  struct i2c_msg_s msgs[2];
   211	  int ret;
   212	
   213	  msgs[0].frequency = frequency;
   214	  msgs[0].addr      = addr;
   215	  msgs[0].flags     = I2C_M_NOSTOP;
   216	  msgs[0].buffer    = &reg;
   217	  msgs[0].length    = 1;
   218	
   219	  msgs[1].frequency = frequency;
   220	  msgs[1].addr      = addr;
   221	  msgs[1].flags     = I2C_M_READ;
   222	  msgs[1].buffer    = value;
   223	  msgs[1].length    = 1;
   224	
   225	  ret = I2C_TRANSFER(i2c, msgs, 2);
   226	  if (ret < 0)
   227	    {
   228	      auderr("ERROR: ES7210 register 0x%02x read failed: %d\n", reg, ret);
   229	    }
   230	
   231	  return ret;
   232	}
