   234	static const char *es7210_reg_name(uint8_t reg)
   235	{
   236	  unsigned int i;
   237	
   238	  for (i = 0; i < sizeof(g_es7210_dump_regs) /
   239	                  sizeof(g_es7210_dump_regs[0]); i++)
   240	    {
