   255	static int es7210_write_verify_reg(struct i2c_master_s *i2c, uint8_t addr,
   256	                                   uint32_t frequency, uint8_t reg,
   257	                                   uint8_t value)
   258	{
   259	  uint8_t readback = 0;
   260	  const char *name;
   261	  int ret;
   262	
   263	  name = es7210_reg_name(reg);
   264	
   265	  ret = es7210_write_reg(i2c, addr, frequency, reg, value);
   266	  if (ret < 0)
   267	    {
   268	      printf("[es7210] write %-12s[0x%02x] want=0x%02x failed: %d\n",
   269	             name, reg, value, ret);
   270	      return ret;
   271	    }
   272	
   273	  usleep(1000);
   274	
   275	  ret = es7210_read_reg(i2c, addr, frequency, reg, &readback);
   276	  if (ret < 0)
   277	    {
   278	      printf("[es7210] verify %-11s[0x%02x] want=0x%02x read failed: %d\n",
   279	             name, reg, value, ret);
   280	      return ret;
   281	    }
   282	
   283	  printf("[es7210] write %-12s[0x%02x] want=0x%02x got=0x%02x%s\n",
   284	         name, reg, value, readback, readback == value ? "" : " mismatch");
   285	
   286	  return OK;
   287	}
