   321	static int es7210_configure(struct i2c_master_s *i2c, uint8_t addr,
   322	                            uint32_t frequency)
   323	{
   324	  unsigned int i;
   325	  int ret;
   326	
   327	  ret = es7210_write_verify_reg(i2c, addr, frequency, ES7210_RESET_REG,
   328	                                ES7210_RESET_VALUE);
   329	  if (ret < 0)
   330	    {
   331	      return ret;
   332	    }
   333	
   334	  usleep(5000);
   335	
   336	  ret = es7210_write_verify_reg(i2c, addr, frequency, ES7210_RESET_REG,
   337	                                ES7210_RESET_RELEASE);
   338	  if (ret < 0)
   339	    {
   340	      return ret;
   341	    }
   342	
   343	  usleep(5000);
   344	
   345	  for (i = 0; i < sizeof(g_es7210_config) / sizeof(g_es7210_config[0]); i++)
   346	    {
   347	      ret = es7210_write_verify_reg(i2c, addr, frequency,
   348	                                    g_es7210_config[i].reg,
   349	                                    g_es7210_config[i].value);
   350	      if (ret < 0)
   351	        {
   352	          return ret;
   353	        }
   354	    }
   355	
   356	  printf("[es7210] configured for BOX-3 microphone capture\n");
   357	  es7210_dump_registers(i2c, addr, frequency);
   358	  return OK;
   359	}
