   403	      return ret;
   404	    }
   405	
   406	  ret = es7210_read_reg(i2c, i2c_addr, i2c_frequency,
   407	                        ES7210_CHIP_VERSION_REG, &chip_version);
   408	  if (ret < 0)
   409	    {
   410	      auderr("ERROR: ES7210 chip version read failed at I2C%d address 0x%02x\n",
   411	             i2c_port, i2c_addr);
   412	      return ret;
   413	    }
   414	
   415	  printf("[es7210] detected: chip_id1=0x%02x chip_id0=0x%02x version=0x%02x\n",
   416	         chip_id1, chip_id0, chip_version);
   417	
   418	  if (chip_id1 != ES7210_CHIP_ID1_VALUE ||
   419	      chip_id0 != ES7210_CHIP_ID0_VALUE)
