   421	      auderr("ERROR: Unexpected ES7210 chip id: 0x%02x 0x%02x\n",
   422	             chip_id1, chip_id0);
   423	      return -ENODEV;
   424	    }
   425	
   426	  return es7210_configure(i2c, i2c_addr, i2c_frequency);
   427	}

