   400	      capture_open = ret == 0;
   401	    }
   402	
   403	  if (ret < 0)
   404	    {
   405	      goto cleanup;
   406	    }
   407	
   408	  printf("[app] source=%s hop=%d ms\n",
   409	         options.mode == INPUT_MODE_FILE ? "file" : "device",
   410	         CONFIG_EXAMPLES_AUDIO_EVENT_HOP_MS);
