{
    if (!dst || dst_size == 0u) {
        return;
    }

    dst[0] = '\0';
    if (!src) {
        return;
    }

    strncpy(dst, src, dst_size - 1u);
    dst[dst_size - 1u] = '\0';
}

static int contains_ctl_or_space(const char *text)
{
    const unsigned char *p = (const unsigned char *)text;

    if (!p) {
        return 1;
    }

    while (*p) {
        if (*p <= 0x20u || *p == 0x7fu) {
            return 1;
        }
        p++;
    }

    return 0;
}

