static int read_file(const char *path, char **buffer_out)
{
    FILE *fp;
    long size;
    char *buffer;
    size_t nread;

    if (!path || !buffer_out) {
        return AGENT_ERROR_INVALID;
    }

    *buffer_out = NULL;
    fp = fopen(path, "rb");
    if (!fp) {
        return AGENT_ERROR_NOTFOUND;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fclose(fp);
        return AGENT_ERROR;
    }
    size = ftell(fp);
    if (size <= 0 || (size_t)size > SMART_HOME_SKILL_READ_MAX) {
        fclose(fp);
        return AGENT_ERROR_LIMIT;
    }
    if (fseek(fp, 0, SEEK_SET) != 0) {
        fclose(fp);
        return AGENT_ERROR;
    }

    buffer = (char *)calloc(1u, (size_t)size + 1u);
    if (!buffer) {
        fclose(fp);
        return AGENT_ERROR_NOMEM;
    }

    nread = fread(buffer, 1u, (size_t)size, fp);
    fclose(fp);
    if (nread != (size_t)size) {
        free(buffer);
        return AGENT_ERROR;
    }

    buffer[nread] = '\0';
    *buffer_out = buffer;
    return AGENT_OK;
}

