    mbedtls_ssl_init(&ctx->ssl);
    mbedtls_ssl_config_init(&ctx->cfg);
    mbedtls_net_init(&ctx->net);
    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
    mbedtls_entropy_init(&ctx->entropy);

    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, mbedtls_entropy_func,
                                 &ctx->entropy,
                                 (const unsigned char *)pers, strlen(pers));
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] ctr_drbg_seed ret=-0x%04x\n", OV_TAG, -ret);
        return AGENT_ERROR_NETWORK;
    }

    if ((ret = mbedtls_net_connect(&ctx->net, host, port,
                                    MBEDTLS_NET_PROTO_TCP)) != 0) {
        syslog(LOG_ERR, "[%s] net_connect %s:%s ret=-0x%04x\n",
               OV_TAG, host, port, -ret);
        return AGENT_ERROR_NETWORK;
    }

    mbedtls_net_set_block(&ctx->net);
    if (ctx->net.fd >= 0) {
        unsigned int tsec = timeout_ms ? (timeout_ms / 1000u) : CAGENT_OV_SOCKET_TIMEOUT_SEC;
