    HDR_APPEND("Host: %s\r\n", host);
    HDR_APPEND("Connection: close\r\n");
    HDR_APPEND("User-Agent: cagent-openvela/1.0\r\n");

    if (body && body_len > 0) {
        HDR_APPEND("Content-Length: %zu\r\n", body_len);
    }

    if (headers_str && headers_str[0] != '\0') {
        HDR_APPEND("%s", headers_str);
    }

