                                request->path,
                                request->headers,
                                (const char *)request->body,
                                request->body_size);
    if (ret != AGENT_OK) {
        ov_tls_ctx_free(&ctx);
        return ret;
    }

    size_t body_len = 0;
    int http_status = ov_tls_read_response(&ctx,
                                            response->body,
