static const char *message_role_name(agent_message_role_t role)
{
    switch (role) {
    case AGENT_MESSAGE_ROLE_USER:
        return "user";
    case AGENT_MESSAGE_ROLE_ASSISTANT:
        return "assistant";
    case AGENT_MESSAGE_ROLE_TOOL:
        return "tool";
    default:
        return NULL;
    }
}

