lv_obj_t *smart_home_lvgl_icon_create(lv_obj_t *parent,
                                      const char *filename,
                                      int width,
                                      int height)
{
    char path[128];
    char fallback[128];
    lv_obj_t *img;
    char *src;

    if (!parent || !filename) {
        return NULL;
    }

    snprintf(path, sizeof(path), "%s/%s.png", SMART_HOME_ICONS_ROOT, filename);
    if (access(path, F_OK) != 0) {
        snprintf(fallback,
                 sizeof(fallback),
                 "%s/%s.png",
                 SMART_HOME_ICONS_FALLBACK_ROOT,
                 filename);
        if (access(fallback, F_OK) == 0) {
            strncpy(path, fallback, sizeof(path) - 1);
            path[sizeof(path) - 1] = '\0';
        }
    }

    img = lv_image_create(parent);
    src = strdup(path);
    if (src) {
        lv_image_set_src(img, src);
        lv_obj_add_event_cb(img, icon_src_delete_cb, LV_EVENT_DELETE, src);
    }
    if (width > 0) {
        lv_obj_set_size(img, width, height > 0 ? height : width);
    }
    return img;
}

