    AGENT_EVENT_TOOL_CALL,       /* 即将执行工具 */
    AGENT_EVENT_TOOL_RESULT,     /* 工具执行完成 */
    AGENT_EVENT_ERROR,           /* 致命错误（非 tool 级错误） */
    AGENT_EVENT_CANCELLED,       /* 请求被取消 */
    AGENT_EVENT_TIMEOUT          /* 请求超时 */
} agent_event_type_t;

