static void agent_post_status(smart_home_lvgl_t *ui, const char *text)
{
    agent_status_t *status;

    if (!ui || !text) {
        return;
    }

    status = (agent_status_t *)calloc(1, sizeof(*status));
    if (!status) {
        return;
    }

    status->ui = ui;
    strncpy(status->text, text, sizeof(status->text) - 1);
    status->text[sizeof(status->text) - 1] = '\0';
    lv_async_call(agent_status_async_cb, status);
}

static void agent_done_async_cb(void *data)
{
    agent_done_t *done = (agent_done_t *)data;
    smart_home_lvgl_t *ui = done ? done->ui : NULL;

    if (!done) {
        return;
    }

    if (ui) {
        ui->request_inflight = 0;
        if (done->ret == AGENT_OK) {
            smart_home_lvgl_finish_thinking(ui);
            smart_home_lvgl_append_msg_bubble(ui, done->output, 0);
            smart_home_lvgl_refresh_cards(ui);
        } else {
            char message[160];
            snprintf(message,
                     sizeof(message),
                     "Agent call failed (%d): %.96s",
                     done->ret,
                     done->output[0] ? done->output : "no detail");
            smart_home_lvgl_finish_thinking(ui);
            smart_home_lvgl_append_error_bubble(ui, message);
        }
        /* Update status hint */
        if (ui->chat_status) {
            lv_label_set_text(ui->chat_status,
                              "Done.  (NSH: smart_home \"...\")");
        }
    }

    free(done);
}

static void *agent_worker_main(void *arg)
{
    agent_job_t *job = (agent_job_t *)arg;
    agent_done_t *done;

    if (!job) {
        return NULL;
    }

    done = (agent_done_t *)calloc(1, sizeof(*done));
    if (!done) {
        if (job->ui) {
            job->ui->request_inflight = 0;
        }
        free(job);
        return NULL;
    }

    done->ui = job->ui;
    agent_post_status(job->ui, "Agent worker started; entering agent_run...");
    done->ret = smart_home_agent_run(job->ui->app,
                                     job->input,
                                     done->output,
                                     sizeof(done->output));
    agent_post_status(job->ui, "Agent worker done; updating UI...");
    lv_async_call(agent_done_async_cb, done);
    free(job);
    return NULL;
}

