#include <stdio.h>
#include <stdlib.h>
#include <syslog.h>

int main(int argc, char *argv[])
{
    smart_home_agent_app_t app;
    int ret;

    printf("=== Smart Home Agent Demo ===\n");
    printf("backend: %s%s model=%s\n",
           SMART_HOME_DEMO_HOST,
           SMART_HOME_DEMO_PATH,
           SMART_HOME_DEMO_MODEL);
    if (argc > 1) {
        printf("input: %s\n\n", argv[1]);
    } else {
#ifdef CONFIG_SMART_HOME_DEMO_UI_LVGL
        printf("starting LVGL UI\n\n");
#else
        printf("type 'quit' to exit\n\n");
#endif
    }

    /* Auto-connect WiFi before initializing the agent.
     * On platforms without WiFi (e.g. goldfish emulator with Ethernet),
     * this may fail — continue anyway and let the HTTP layer use whatever
     * network is available.
     */

    ret = smart_home_wifi_connect();
    if (ret < 0) {
        syslog(LOG_WARNING, "WiFi connect failed: %d. "
               "Continuing with existing network.\n", ret);
        fprintf(stderr, "WiFi connect failed: %d (continuing)\n", ret);
    }

    ret = smart_home_agent_app_init(&app);
    if (ret != AGENT_OK) {
        fprintf(stderr, "smart_home_agent_app_init failed: %d\n", ret);
        return EXIT_FAILURE;
    }

#ifdef CONFIG_SMART_HOME_DEMO_UI_LVGL
    if (argc > 1) {
        ret = smart_home_ui_run_once(&app, argv[1]);
    } else {
        ret = smart_home_lvgl_run(&app, NULL);
    }
#else
    if (argc > 1) {
        ret = smart_home_ui_run_once(&app, argv[1]);
    } else {
        ret = smart_home_ui_run(&app);
    }
#endif

    smart_home_agent_app_deinit(&app);
    return ret == AGENT_OK ? EXIT_SUCCESS : EXIT_FAILURE;
}

