/**
 * smart_home LVGL agent bridge.
 */

#include "smart_home_lvgl_internal.h"

#include "../../config/smart_home_config.h"

#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define SMART_HOME_AGENT_WORKER_STACK_SIZE (256 * 1024)

typedef struct {
    smart_home_lvgl_t *ui;
    char input[SMART_HOME_INPUT_SIZE];
} agent_job_t;

typedef struct {
    smart_home_lvgl_t *ui;
    int ret;
    char output[SMART_HOME_OUTPUT_SIZE];
} agent_done_t;

typedef struct {
    smart_home_lvgl_t *ui;
    char text[96];
} agent_status_t;

typedef struct {
    smart_home_lvgl_t *ui;
    agent_event_type_t type;
    uint64_t timestamp_ms;
    uint32_t iteration;
    int error_code;
    char message[128];
    char tool_name[64];
    char tool_call_id[64];
    char trace_id[64];
    char session_id[64];
} ui_event_payload_t;

static void agent_status_async_cb(void *data)
{
    agent_status_t *status = (agent_status_t *)data;

    if (!status) {
        return;
    }

    if (status->ui && status->ui->chat_status) {
        lv_label_set_text(status->ui->chat_status, status->text);
    }

    free(status);
}

static void agent_post_status(smart_home_lvgl_t *ui, const char *text)
{
    agent_status_t *status;

    if (!ui || !text) {
        return;
    }

    status = (agent_status_t *)calloc(1, sizeof(*status));
    if (!status) {
        return;
    }

    status->ui = ui;
    strncpy(status->text, text, sizeof(status->text) - 1);
    status->text[sizeof(status->text) - 1] = '\0';
    lv_async_call(agent_status_async_cb, status);
}

static void agent_done_async_cb(void *data)
{
    agent_done_t *done = (agent_done_t *)data;
    smart_home_lvgl_t *ui = done ? done->ui : NULL;

    if (!done) {
        return;
    }

    if (ui) {
        ui->request_inflight = 0;
        if (done->ret == AGENT_OK) {
            smart_home_lvgl_finish_thinking(ui);
            smart_home_lvgl_append_msg_bubble(ui, done->output, 0);
            smart_home_lvgl_refresh_cards(ui);
        } else {
            char message[160];
            snprintf(message,
                     sizeof(message),
                     "Agent call failed (%d): %.96s",
                     done->ret,
                     done->output[0] ? done->output : "no detail");
            smart_home_lvgl_finish_thinking(ui);
            smart_home_lvgl_append_error_bubble(ui, message);
        }
        /* Update status hint */
        if (ui->chat_status) {
            lv_label_set_text(ui->chat_status,
                              "Done.  (NSH: smart_home \"...\")");
        }
    }

    free(done);
}

static void *agent_worker_main(void *arg)
{
    agent_job_t *job = (agent_job_t *)arg;
    agent_done_t *done;

    if (!job) {
        return NULL;
    }

    done = (agent_done_t *)calloc(1, sizeof(*done));
    if (!done) {
        if (job->ui) {
            job->ui->request_inflight = 0;
        }
        free(job);
        return NULL;
    }

    done->ui = job->ui;
    agent_post_status(job->ui, "Agent worker started; entering agent_run...");
    done->ret = smart_home_agent_run(job->ui->app,
                                     job->input,
                                     done->output,
                                     sizeof(done->output));
    agent_post_status(job->ui, "Agent worker done; updating UI...");
    lv_async_call(agent_done_async_cb, done);
    free(job);
    return NULL;
}

int smart_home_lvgl_submit_agent_job(smart_home_lvgl_t *ui, const char *text)
{
    pthread_t tid;
    agent_job_t *job;
    int ret;

    if (!ui || !ui->app || !text || !text[0]) {
        return AGENT_ERROR_INVALID;
    }

    if (ui->request_inflight) {
        smart_home_lvgl_append_error_bubble(ui, "Previous request is still running.");
        return AGENT_ERROR_BUSY;
    }

    job = (agent_job_t *)calloc(1, sizeof(*job));
    if (!job) {
        smart_home_lvgl_append_error_bubble(ui, "Not enough memory to submit request.");
        return AGENT_ERROR_NOMEM;
    }

    job->ui = ui;
    strncpy(job->input, text, sizeof(job->input) - 1);
    ui->request_inflight = 1;

    {
        pthread_attr_t attr;

        pthread_attr_init(&attr);
        ret = pthread_attr_setstacksize(&attr,
                                        SMART_HOME_AGENT_WORKER_STACK_SIZE);
        if (ret != 0) {
            pthread_attr_destroy(&attr);
            ui->request_inflight = 0;
            free(job);
            smart_home_lvgl_append_error_bubble(
                ui,
                "Failed to configure Agent worker stack.");
            return AGENT_ERROR;
        }

        ret = pthread_create(&tid, &attr, agent_worker_main, job);
        pthread_attr_destroy(&attr);
    }
    if (ret != 0) {
        ui->request_inflight = 0;
        free(job);
        smart_home_lvgl_append_error_bubble(ui, "Failed to create Agent worker.");
        return AGENT_ERROR;
    }

    pthread_detach(tid);
    return AGENT_OK;
}

static void ui_event_async_cb(void *data)
{
    ui_event_payload_t *payload = (ui_event_payload_t *)data;
    smart_home_lvgl_t *ui;

    if (!payload) {
        return;
    }

    ui = payload->ui;
    if (!ui) {
        free(payload);
        return;
    }

    smart_home_lvgl_trace_event(ui,
                                payload->type,
                                payload->timestamp_ms,
                                payload->iteration,
                                payload->error_code,
                                payload->message,
                                payload->tool_name,
                                payload->tool_call_id,
                                payload->trace_id,
                                payload->session_id);

    switch (payload->type) {
    case AGENT_EVENT_MODEL_REQUEST:
        smart_home_lvgl_show_thinking(ui);
        break;
    case AGENT_EVENT_TOOL_CALL:
        smart_home_lvgl_trace_tool(ui,
                                   payload->tool_name,
                                   payload->tool_call_id,
                                   -1);
        break;
    case AGENT_EVENT_TOOL_RESULT:
        if (strcmp(payload->tool_name, "set_light") == 0 ||
            strcmp(payload->tool_name, "set_ac") == 0 ||
            strcmp(payload->tool_name, "run_scene") == 0) {
            smart_home_lvgl_refresh_cards(ui);
        }
        smart_home_lvgl_trace_tool(ui,
                                   payload->tool_name,
                                   payload->tool_call_id,
                                   payload->error_code == AGENT_OK ? 1 : 0);
        break;
    case AGENT_EVENT_ERROR:
    case AGENT_EVENT_CANCELLED:
    case AGENT_EVENT_TIMEOUT:
        smart_home_lvgl_finish_thinking(ui);
        smart_home_lvgl_append_error_bubble(ui, payload->message);
        break;
    case AGENT_EVENT_RUN_DONE:
        if (payload->error_code != AGENT_OK) {
            smart_home_lvgl_finish_thinking(ui);
            smart_home_lvgl_append_error_bubble(ui, payload->message);
        }
        break;
    default:
        break;
    }

