    content_w = smart_home_lvgl_content_w();
    input_y = -SMART_HOME_NAV_H - SMART_HOME_NAV_BOTTOM_PAD - 8;

    if (ui->chat_list) {
        lv_obj_set_size(ui->chat_list,
                        content_w,
