void smart_home_lvgl_event_cb(const agent_event_t *event, void *user_data)
{
    smart_home_lvgl_t *ui = (smart_home_lvgl_t *)user_data;
    ui_event_payload_t *payload;

    if (!ui || !event) {
        return;
    }

    payload = (ui_event_payload_t *)calloc(1, sizeof(*payload));
    if (!payload) {
        return;
    }

    payload->ui = ui;
    payload->type = event->type;
    payload->timestamp_ms = event->timestamp_ms;
    payload->iteration = event->iteration;
    payload->error_code = event->error_code;

    if (event->message) {
        strncpy(payload->message, event->message, sizeof(payload->message) - 1);
        payload->message[sizeof(payload->message) - 1] = '\0';
    }
    if (event->tool_name) {
        strncpy(payload->tool_name,
                event->tool_name,
                sizeof(payload->tool_name) - 1);
        payload->tool_name[sizeof(payload->tool_name) - 1] = '\0';
    }
    if (event->tool_call_id) {
        strncpy(payload->tool_call_id,
                event->tool_call_id,
                sizeof(payload->tool_call_id) - 1);
        payload->tool_call_id[sizeof(payload->tool_call_id) - 1] = '\0';
    }
    if (event->trace_id) {
        strncpy(payload->trace_id,
                event->trace_id,
                sizeof(payload->trace_id) - 1);
        payload->trace_id[sizeof(payload->trace_id) - 1] = '\0';
    }
    if (event->session_id) {
        strncpy(payload->session_id,
                event->session_id,
                sizeof(payload->session_id) - 1);
        payload->session_id[sizeof(payload->session_id) - 1] = '\0';
    }

    lv_async_call(ui_event_async_cb, payload);
}

