/* ── chat_send_text: used by NSH command-line input path ───── */

void smart_home_lvgl_chat_send_text(smart_home_lvgl_t *ui, const char *text)
{
    int ret;

    if (!ui || !text || !text[0]) {
        return;
    }

    /* Show user bubble */
    smart_home_lvgl_append_msg_bubble(ui, text, 1);

    /* Show an immediate trace card while waiting for RUN_START. */
    smart_home_lvgl_show_thinking(ui);

    if (ui->chat_status) {
        lv_label_set_text(ui->chat_status, "Submitting Agent request...");
    }

    /* Submit to worker thread */
    ret = smart_home_lvgl_submit_agent_job(ui, text);
    if (ret != AGENT_OK) {
        char message[96];

        smart_home_lvgl_finish_thinking(ui);
        snprintf(message,
                 sizeof(message),
                 "Failed to submit Agent request (%d).",
                 ret);
        smart_home_lvgl_append_error_bubble(ui, message);
        if (ui->chat_status) {
            lv_label_set_text(ui->chat_status, "Agent submit failed.");
        }
        return;
    }

    /* Update status hint */
    if (ui->chat_status) {
        lv_label_set_text(ui->chat_status,
                          "Agent worker submitted; waiting for RUN_START...");
    }
}

