   156	                                      int height)
   157	{
   158	    char posix_path[128];
   159	    char lvgl_path[130];
   160	    char fallback[128];
   161	    lv_obj_t *img;
   162	    char *src;
   163	
   164	    if (!parent || !filename) {
   165	        return NULL;
   166	    }
   167	
   168	    /* Check file existence via POSIX path (access()) */
   169	
   170	    snprintf(posix_path, sizeof(posix_path),
   171	             "%s/%s.png", SMART_HOME_ICONS_ROOT, filename);
   172	    if (access(posix_path, F_OK) != 0) {
   173	        snprintf(fallback, sizeof(fallback),
   174	                 "%s/%s.png", SMART_HOME_ICONS_FALLBACK_ROOT, filename);
   175	        if (access(fallback, F_OK) == 0) {
   176	            strncpy(posix_path, fallback, sizeof(posix_path) - 1);
   177	            posix_path[sizeof(posix_path) - 1] = '\0';
   178	        }
   179	    }
   180	
   181	    /* Build LVGL path with drive letter prefix */
   182	
   183	    snprintf(lvgl_path, sizeof(lvgl_path),
   184	             SMART_HOME_LV_FS_PREFIX "%s", posix_path);
   185	
