/* ── Icon helpers ─────────────────────────────────────── */

static void icon_src_delete_cb(lv_event_t *event)
{
    char *src = (char *)lv_event_get_user_data(event);

    free(src);
}

lv_obj_t *smart_home_lvgl_icon_create(lv_obj_t *parent,
                                      const char *filename,
                                      int width,
                                      int height)
{
    char posix_path[128];
    char lvgl_path[130];
    char fallback[128];
    lv_obj_t *img;
    char *src;

    if (!parent || !filename) {
        return NULL;
    }

    /* Check file existence via POSIX path (access()) */

    snprintf(posix_path, sizeof(posix_path),
             "%s/%s.png", SMART_HOME_ICONS_ROOT, filename);
    if (access(posix_path, F_OK) != 0) {
        snprintf(fallback, sizeof(fallback),
                 "%s/%s.png", SMART_HOME_ICONS_FALLBACK_ROOT, filename);
        if (access(fallback, F_OK) == 0) {
            strncpy(posix_path, fallback, sizeof(posix_path) - 1);
            posix_path[sizeof(posix_path) - 1] = '\0';
        }
    }

    /* Build LVGL path with drive letter prefix */

    snprintf(lvgl_path, sizeof(lvgl_path),
             SMART_HOME_LV_FS_PREFIX "%s", posix_path);

    img = lv_image_create(parent);
    src = strdup(lvgl_path);
    if (src) {
        lv_image_set_src(img, src);
        lv_obj_add_event_cb(img, icon_src_delete_cb, LV_EVENT_DELETE, src);
    }
    if (width > 0) {
        lv_obj_set_size(img, width, height > 0 ? height : width);
    }
    return img;
}

lv_obj_t *smart_home_lvgl_icon_with_text(lv_obj_t *parent,
                                          const char *filename,
                                          int icon_w,
                                          int icon_h,
                                          const char *text,
                                          lv_color_t text_color,
                                          int text_size)
{
    lv_obj_t *cont = lv_obj_create(parent);
    lv_obj_t *icon;
    lv_obj_t *label;

    lv_obj_remove_style_all(cont);
    lv_obj_set_size(cont, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(cont, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(cont, 0, 0);
    lv_obj_set_flex_flow(cont, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(cont, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    icon = smart_home_lvgl_icon_create(cont, filename, icon_w, icon_h);
    if (icon) {
        lv_obj_set_style_margin_bottom(icon, 4, 0);
    }

    label = smart_home_lvgl_label_create(cont, text, text_color, text_size);
    lv_obj_set_style_text_align(label, LV_TEXT_ALIGN_CENTER, 0);

    return cont;
}

text:
可以。LVGL 自带“图标”主要是 **Symbol 字体图标**，不是 PNG。它们本质是特殊 Unicode 字符，通过 `LV_SYMBOL_XXX` 宏显示在 `lv_label`、`lv_btn`、`lv_dropdown` 等控件里。

典型用法：

```c
lv_obj_t *label = lv_label_create(parent);
lv_label_set_text(label, LV_SYMBOL_HOME);
```

或者图标 + 文字：

```c
lv_label_set_text(label, LV_SYMBOL_HOME " Panel");
```

在你这个项目里，最适合先替换这几类 PNG：

```text
ICON_NAV_HOME      -> LV_SYMBOL_HOME
ICON_NAV_CHAT      -> LV_SYMBOL_COMMENTS 或 LV_SYMBOL_EDIT
ICON_NAV_SETTINGS  -> LV_SYMBOL_SETTINGS
ICON_ADD           -> LV_SYMBOL_PLUS
ICON_DELETE        -> LV_SYMBOL_TRASH
ICON_BACK          -> LV_SYMBOL_LEFT
ICON_CANCEL        -> LV_SYMBOL_CLOSE
ICON_STATUS_OK     -> LV_SYMBOL_OK
ICON_STATUS_FAIL   -> LV_SYMBOL_CLOSE
ICON_LOADING       -> LV_SYMBOL_REFRESH
ICON_TOOL          -> LV_SYMBOL_SETTINGS
ICON_WIFI          -> LV_SYMBOL_WIFI
```

优点：

- 不依赖 `/data/res/icons/*.png`
- 不依赖 LVGL FS_POSIX
- 不依赖 PNG decoder
- 不需要处理 200x200 PNG 缩放问题
- 在模拟器和 ESP32-S3 BOX-3 上更稳定

限制：

- 样式没有 PNG 精致。
- LVGL 内置 symbol 集合有限，不一定有灯、空调、卧室这种业务图标。
- 要确保使用的字体包含 LVGL symbols。通常 LVGL 内置 Montserrat 字体带这些 symbol，但如果全部换成自定义 TTF，需要注意 fallback。

在项目里的落地方式，我建议不要到处手改 `smart_home_lvgl_icon_create()` 调用，而是改图标 helper，让它支持“PNG 优先，失败用 LV_SYMBOL 兜底”：

```c
static const char *smart_home_lvgl_symbol_for_icon(const char *filename)
{
    if (strcmp(filename, ICON_NAV_HOME) == 0) {
        return LV_SYMBOL_HOME;
    }
    if (strcmp(filename, ICON_NAV_CHAT) == 0) {
        return LV_SYMBOL_EDIT;
    }
    if (strcmp(filename, ICON_NAV_SETTINGS) == 0) {
        return LV_SYMBOL_SETTINGS;
    }
    if (strcmp(filename, ICON_ADD) == 0) {
        return LV_SYMBOL_PLUS;
    }
    if (strcmp(filename, ICON_DELETE) == 0) {
        return LV_SYMBOL_TRASH;
    }
    if (strcmp(filename, ICON_STATUS_OK) == 0) {
        return LV_SYMBOL_OK;
    }
    if (strcmp(filename, ICON_STATUS_FAIL) == 0) {
        return LV_SYMBOL_CLOSE;
    }
    if (strcmp(filename, ICON_LOADING) == 0) {
        return LV_SYMBOL_REFRESH;
    }
    if (strcmp(filename, ICON_TOOL) == 0) {
        return LV_SYMBOL_SETTINGS;
    }

    return LV_SYMBOL_DUMMY;
}
```

然后在 `smart_home_lvgl_icon_create()` 里，如果 PNG 文件不存在或暂时不想用 PNG，就创建 label：

```c
lv_obj_t *label = lv_label_create(parent);
lv_label_set_text(label, symbol);
lv_obj_set_style_text_font(label, smart_home_lvgl_font(16), 0);
lv_obj_set_style_text_color(label, SMART_HOME_UI_COLOR_TEXT_MUTED, 0);
return label;
```

但这里有个注意点：现在函数名叫 `smart_home_lvgl_icon_create()`，调用方认为它返回的是 image，但实际只当成 `lv_obj_t *` 用，所以返回 label 是可行的。比如 nav、panel、trace 里只是居中、设置 margin，不依赖 image 专有 API。

更稳的策略是：

```text
短期调试：强制使用 LV_SYMBOL，绕开 PNG 路径问题
中期方案：PNG 优先，失败 fallback 到 LV_SYMBOL
最终产品：业务图标用小尺寸 PNG，通用操作图标用 LV_SYMBOL
```

我建议你现在先走“强制 LV_SYMBOL fallback”路线。这样可以快速确认 Panel 空白是不是 PNG 图标导致的。如果 LV_SYMBOL 能显示，而卡片仍空白，那问题就不是图标资源。
